// Motor de reglas financieras
const transactions = $node['Consultar transacciones'].all.map(i => i.json);
const totalIngresos = parseFloat($node['Consultar ingresos del mes'].first.json.total_ingresos);
const userId = $node['Webhook: Nueva transacci\u00f3n'].first.json.body.userId;
const recommendations = [];

// Agrupar gastos por categoría
const gastosPorCategoria = {};
const gastosRecientes = {};
let totalEgresos = 0;

transactions.forEach(t => {
  if (t.tipo === 'egreso') {
    totalEgresos += parseFloat(t.monto);
    const cat = t.category?.nombre || 'Sin categoría';
    gastosPorCategoria[cat] = (gastosPorCategoria[cat] || 0) + parseFloat(t.monto);

    // Track recent spending for subscription detection (store date + amount)
    const key = `${cat}-${t.descripcion || 'sin-desc'}`;
    if (!gastosRecientes[key]) gastosRecientes[key] = [];
    gastosRecientes[key].push({ fecha: new Date(t.fecha), monto: parseFloat(t.monto) });
  }
});

// Regla 1: Gasto en categoría > 30% del ingreso mensual
if (totalIngresos > 0) {
  for (const [cat, total] of Object.entries(gastosPorCategoria)) {
    const porcentaje = (total / totalIngresos) * 100;
    if (porcentaje > 30) {
      recommendations.push({
        user_id: userId,
        contenido: `Tu gasto en ${cat} representa el ${porcentaje.toFixed(1)}% de tus ingresos. Considera reducirlo para mantener un balance saludable.`,
        tipo: 'alerta',
        leida: false
      });
    }
  }
}

// Regla 2: Gastos totales > 80% de ingresos
if (totalIngresos > 0 && (totalEgresos / totalIngresos) > 0.8) {
  recommendations.push({
    user_id: userId,
    contenido: 'Tus gastos superan el 80% de tus ingresos este mes. Es recomendable mantener los gastos por debajo del 70% para poder ahorrar.',
    tipo: 'alerta',
    leida: false
  });
}

// Regla 3: Sin ahorro registrado
const hayAhorro = transactions.some(t => 
  t.tipo === 'egreso' && t.category?.nombre?.toLowerCase().includes('ahorro')
);
if (!hayAhorro && totalIngresos > 0) {
  recommendations.push({
    user_id: userId,
    contenido: 'No hemos registrado movimientos de ahorro este mes. Te recomendamos destinar al menos el 10% de tus ingresos a una meta de ahorro.',
    tipo: 'ahorro',
    leida: false
  });
}

// Regla 4: Gastos recurrentes (posibles suscripciones)
// Improved: checks similar amounts (within 20% variance) AND evenly spaced dates (stddev within 5 days)
for (const [key, entries] of Object.entries(gastosRecientes)) {
  if (entries.length >= 3) {
    const dates = entries.map(e => e.fecha).sort((a, b) => new Date(a) - new Date(b));
    const amounts = entries.map(e => e.monto);

    // Check similar amounts (within 20% variance from mean)
    const avgAmount = amounts.reduce((s, a) => s + a, 0) / amounts.length;
    const maxDev = amounts.reduce((max, a) => Math.max(max, Math.abs(a - avgAmount) / Math.max(avgAmount, 1)), 0);
    const amountsSimilar = maxDev <= 0.20;

    // Check evenly spaced intervals (stddev <= 5 days)
    let intervals = [];
    for (let i = 1; i < dates.length; i++) {
      intervals.push((new Date(dates[i]) - new Date(dates[i-1])) / (1000 * 60 * 60 * 24));
    }
    const meanInt = intervals.reduce((s, d) => s + d, 0) / intervals.length;
    const variance = intervals.reduce((s, d) => s + Math.pow(d - meanInt, 2), 0) / intervals.length;
    const stddev = Math.sqrt(variance);
    const evenlySpaced = stddev <= 5;

    if (amountsSimilar || evenlySpaced) {
      const [cat] = key.split('-');
      recommendations.push({
        user_id: userId,
        contenido: `Hemos detectado gastos recurrentes en ${cat} (${entries.length} veces este mes). Podría ser una suscripción que vale la pena revisar.`,
        tipo: 'consejo',
        leida: false
      });
    }
  }
}

// Return recommendations as a single item with the full array for batch POST
return [{ json: { recommendations } }];
